import{_ as e,o,c as d,a2 as c}from"./chunks/framework.BM5YPQmL.js";const O=JSON.parse('{"title":"OCBL——Open Cube OS 引导加载器：架构与职责","description":"","frontmatter":{},"headers":[],"relativePath":"zh/components/ocbl/ocbl-architecture.md","filePath":"zh/components/ocbl/ocbl-architecture.md"}'),a={name:"zh/components/ocbl/ocbl-architecture.md"};function r(l,t,b,i,n,h){return o(),d("div",null,[...t[0]||(t[0]=[c('<h1 id="ocbl——open-cube-os-引导加载器-架构与职责" tabindex="-1">OCBL——Open Cube OS 引导加载器：架构与职责 <a class="header-anchor" href="#ocbl——open-cube-os-引导加载器-架构与职责" aria-label="Permalink to &quot;OCBL——Open Cube OS 引导加载器：架构与职责&quot;">​</a></h1><p>OCBL 是 Open Cube OS 的原生引导加载器。它在 Open Cube OS 的各类 介质上取代 GRUB：<code>ocbl-install</code> 写入的引导代码、恢复盘的 stage1、 ISO 的引导镜像都是 OCBL。它位于 <code>ocbl/</code>，从一份共享核心构建出 <strong>两种固件形态</strong>。</p><h2 id="一份核心-两种固件形态" tabindex="-1">一份核心，两种固件形态 <a class="header-anchor" href="#一份核心-两种固件形态" aria-label="Permalink to &quot;一份核心，两种固件形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>入口</th><th>实模式管线</th><th>控制台</th><th>磁盘</th><th>视频</th></tr></thead><tbody><tr><td>BIOS</td><td><code>bios/stage1.asm</code></td><td>16 位跳板（<code>tramp16.asm</code>），int13 DAP 经 1 MiB 以下弹跳窗读取</td><td>VGA 文本 + 串行</td><td>int13</td><td>VBE（<code>ocbl_vbe.c</code>）</td></tr><tr><td>UEFI</td><td><code>efi/efi_entry.c</code></td><td>无——从头就是原生 64 位</td><td>GOP 控制台 + 串行</td><td>EFI BlockIo（<strong>驱动器编号从零开始</strong>）</td><td>GOP（<code>ocbl_gop_efi.c</code>）</td></tr></tbody></table><p>两种形态编译同一份 <code>common/</code> 核心：条目扫描器（<code>ocbl_scan.c</code>）、 菜单（<code>ocbl_menu.c</code>）、文件系统（<code>ocbl_fs.c</code>）、分区解码 （<code>ocbl_part.c</code>）、ELF 加载器（<code>ocbl_load.c</code>）、启动状态监视器 （<code>ocbl_statemon.c</code>）与看门狗驱动（<code>ocbl_wdt.c</code>）。</p><h2 id="移交契约" tabindex="-1">移交契约 <a class="header-anchor" href="#移交契约" aria-label="Permalink to &quot;移交契约&quot;">​</a></h2><p>OCBL 加载内核并按与 GRUB 完全一致的方式移交——32 位保护模式、 分页关闭、<code>EAX = 0x36D76289</code>（multiboot2 魔数）、<code>EBX</code> = MBI 物理地址、跳转到内核的 32 位入口。BIOS 形态加载的固定物理布局：</p><table tabindex="0"><thead><tr><th>地址</th><th>内容</th></tr></thead><tbody><tr><td><code>0x30000</code>-<code>0x3FFFF</code></td><td>64 KiB 读取弹跳窗（int13 DAP 必须落在 1 MiB 以下）</td></tr><tr><td><code>0x50000</code></td><td>multiboot2 信息（64 KiB）</td></tr><tr><td><code>0x400000+</code></td><td>内核 PT_LOAD 段（内核链接基址）</td></tr><tr><td><code>0x800000+</code></td><td>mb2 &quot;self&quot; 模块的内核 ELF 副本</td></tr><tr><td><code>0x1000000+</code></td><td>OCIRE 载荷（菜单条目 OCBL_ENT_OCIRE）</td></tr></tbody></table><p>UEFI 形态保持同样的 MBI 契约，但以退出启动服务代替降级回实模式。</p><h2 id="ocbl-扫描什么" tabindex="-1">OCBL 扫描什么 <a class="header-anchor" href="#ocbl-扫描什么" aria-label="Permalink to &quot;OCBL 扫描什么&quot;">​</a></h2><p>扫描器遍历每个 BIOS 驱动器与启动光盘，解码分区表、挂载它认识的 文件系统，产出菜单渲染用的条目表。七类条目：</p><table tabindex="0"><thead><tr><th>类</th><th>识别依据</th></tr></thead><tbody><tr><td>OCOS</td><td>任何携带 multiboot2 魔数头部的 <code>/boot/opencube.elf</code> 卷；A/B 标志协议选择槽位</td></tr><tr><td>OCIRE</td><td>携带 <code>/boot/ocire.elf</code> 的 0xEE 影子卷（或任意卷）；WP-07 恢复盘上是两个独立槽分区</td></tr><tr><td>OCSE</td><td>携带 <code>/ocse.marker</code> 的 ISO9660 卷（安装介质契约）</td></tr><tr><td>WINDOWS</td><td>携带 <code>/EFI/Microsoft/Boot/bootmgfw.efi</code> 的卷</td></tr><tr><td>LINUX</td><td>带外来 EFI 加载器的 ESP（<code>/EFI/&lt;vendor&gt;/</code> 下的 <code>grubx64.efi</code> / <code>shimx64.efi</code> / <code>systemd-bootx64.efi</code>）——vendor 目录名即条目名</td></tr><tr><td>GENERIC</td><td>带不匹配上述任何一项的 <code>/EFI/BOOT/BOOTX64.EFI</code> 的 ESP</td></tr><tr><td>SHUTDOWN</td><td>合成条目，永远排最后</td></tr></tbody></table><p>已声明的限制：3.0.0 的 OCBL 不带 ext2/3/4 驱动，Linux 系统经其 ESP 加载器识别、绝不读取 ext 根上的 <code>/boot</code>；Windows 同理（不解析 NTFS——识别基于 ESP，引导基于链式加载）。</p><h2 id="加载之外的职责" tabindex="-1">加载之外的职责 <a class="header-anchor" href="#加载之外的职责" aria-label="Permalink to &quot;加载之外的职责&quot;">​</a></h2><p>OCBL 还是可靠性链的<strong>第一响应者</strong>：</p><ul><li>每次受监视载荷移交前布防引导阶段看门狗预算（i6300ESB 接力）；</li><li>复位后从状态区诊断上一次启动；</li><li>记录启动失败、累计连续失败数，达到阈值时把机器路由进 OCIRE。</li></ul><p>这些机制详见<a href="./ocbl-ab.html">双固件引导与 A/B 槽判定</a>与 <a href="./ocbl-troubleshooting.html">故障排查与状态码</a>。</p>',17)])])}const p=e(a,[["render",r]]);export{O as __pageData,p as default};
